-- =============================================================================
-- 509 — LE CAHIER D'EXERCICES DE 2DE (partie 11)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 509 --niveau 2de --fichiers physique-chimie.n2,ses.n1 --suffixe 11 > supabase/contenu/509_exercices_2de_11.sql
--
-- 69 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   physique-chimie.n2      33 exercices · 11 chapitres
--   ses.n1                  36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('1d74eec5-d615-5c6e-a540-bf3b0314550d'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un skieur sur la piste rouge","competence":"observer-schema","situation":"Pour son club, Axel filme un skieur qui descend une longue piste droite. Il repère sa position toutes les 1,0 s : c’est une chronophotographie. L’échelle est donnée sous le dessin.","documents":[{"id":"chrono","type":"schema","titre":"Chronophotographie du skieur","largeur":340,"hauteur":210,"elements":[{"forme":"ligne","de":[20,110],"a":[320,110],"style":"pointilles","teinte":"gris"},{"forme":"cercle","cx":40,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z1","zone":true},{"forme":"texte","x":40,"y":138,"texte":"M0","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":80,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"texte","x":80,"y":138,"texte":"M1","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":120,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":120,"y":138,"texte":"M2","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":160,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":160,"y":138,"texte":"M3","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":200,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":200,"y":138,"texte":"M4","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":240,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z6","zone":true},{"forme":"texte","x":240,"y":138,"texte":"M5","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":280,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z7","zone":true},{"forme":"texte","x":280,"y":138,"texte":"M6","ancre":"milieu","taille":"petit"},{"forme":"texte","x":170,"y":30,"texte":"Une position toutes les 1,0 s","ancre":"milieu","taille":"normal"},{"forme":"ligne","de":[40,175],"a":[140,175],"fleche":"deux","teinte":"encre"},{"forme":"texte","x":90,"y":196,"texte":"30 m sur le terrain","ancre":"milieu","taille":"petit"}],"source":"Schéma écrit pour l’exercice, vue de dessus"}],"questions":[{"enonce":"Touche la position du skieur 4,0 s après le départ en M0.","aide":"Une position est notée toutes les 1,0 s : compte les intervalles depuis M0.","type":"zone","document":"chrono","multiple":false},{"enonce":"Avec l’échelle, quelle distance sépare M1 de M3 sur le terrain ?","aide":"Sur le dessin, M1M3 mesure 80 unités et la règle en mesure 100 : elle vaut 30 m.","type":"nombre","unite":"m"},{"enonce":"On estime la vitesse en M2 par v = M1M3 / (2τ), avec τ = 1,0 s. Quelle est la valeur de v en M2 ?","aide":"Divise la distance M1M3 par la durée 2τ = 2,0 s.","type":"nombre","unite":"m·s⁻¹"},{"enonce":"Les points sont alignés et régulièrement espacés. Que dire du vecteur vitesse du skieur ?","aide":"Compare les distances entre deux positions successives.","type":"choix","options":[{"id":"a","texte":"Sa valeur augmente à chaque nouvelle position"},{"id":"b","texte":"Il est nul puisque le skieur reste sur la piste"},{"id":"c","texte":"Sa direction change à chaque nouvel instant"},{"id":"d","texte":"Il ne change pas : même direction, même valeur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"Il y a 1,0 s entre deux positions : après 4,0 s, le skieur est en **M4**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 m","explication":"M1M3 = 80 unités, soit 80/100 × 30 m = **24 m**."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 m·s⁻¹","explication":"v(M2) ≈ M1M3 / (2τ) = 24 m / 2,0 s = **12 m·s⁻¹**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Distances égales en des durées égales : la valeur est constante ; trajectoire droite : la direction l’est aussi. Le vecteur vitesse **ne varie pas** (mouvement rectiligne uniforme)."}]$ex$::jsonb),
  ('1d74eec5-d615-5c6e-a540-bf3b0314550d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La nacelle de la grande roue","competence":"observer-schema","situation":"Dans une fête foraine, une nacelle tourne à vitesse de valeur constante. Maëlle veut comprendre pourquoi son vecteur vitesse change quand même : elle compare la vitesse en M1 et en M3.","documents":[{"id":"roue","type":"schema","titre":"Trajectoire et vecteurs vitesse","largeur":340,"hauteur":230,"elements":[{"forme":"cercle","cx":170,"cy":125,"r":80,"teinte":"gris","motif":"aucun"},{"forme":"ligne","de":[170,125],"a":[250,125],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[170,125],"a":[170,45],"style":"pointilles","teinte":"gris"},{"forme":"cercle","cx":170,"cy":125,"r":3,"teinte":"encre","motif":"plein"},{"forme":"texte","x":170,"y":145,"texte":"centre C","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":250,"cy":125,"r":6,"teinte":"violet","motif":"plein"},{"forme":"texte","x":272,"y":130,"texte":"M1","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":170,"cy":45,"r":6,"teinte":"violet","motif":"plein"},{"forme":"texte","x":170,"y":30,"texte":"M3","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[250,125],"a":[250,75],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z1","zone":true},{"forme":"ligne","de":[170,45],"a":[120,45],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z2","zone":true},{"forme":"texte","x":170,"y":215,"texte":"Nacelle à vitesse de valeur constante : 2,0 m·s⁻¹ ↔ 50 unités","ancre":"milieu","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"},{"id":"constr","type":"schema","titre":"Construction de la variation de vitesse","largeur":340,"hauteur":230,"elements":[{"forme":"cercle","cx":200,"cy":150,"r":4,"teinte":"encre","motif":"plein"},{"forme":"ligne","de":[200,150],"a":[200,100],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z3","zone":true},{"forme":"ligne","de":[200,150],"a":[150,150],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z4","zone":true},{"forme":"ligne","de":[200,100],"a":[150,150],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z5","zone":true},{"forme":"texte","x":210,"y":170,"texte":"point commun","ancre":"milieu","taille":"petit"},{"forme":"texte","x":170,"y":215,"texte":"Les deux vecteurs vitesse reportés depuis un même point","ancre":"milieu","taille":"petit","italique":true}],"source":"Mêmes vecteurs, mêmes longueurs"}],"questions":[{"enonce":"Touche le vecteur vitesse de la nacelle quand elle passe en M1.","aide":"Le vecteur vitesse part du point où se trouve la nacelle et il est tangent au cercle.","type":"zone","document":"roue","multiple":false},{"enonce":"La variation du vecteur vitesse relie les extrémités des deux vecteurs. Touche-la.","aide":"Elle ne part pas du point commun : elle joint l’extrémité du premier vecteur à celle du second.","type":"zone","document":"constr","multiple":false},{"enonce":"L’échelle est 2,0 m·s⁻¹ pour 50 unités. La flèche de variation mesure 70,7 unités. Quelle est la valeur de Δv ? (Arrondis à 0,1 m·s⁻¹.)","aide":"Produit en croix : 50 unités ↔ 2,0 m·s⁻¹.","type":"nombre","unite":"m·s⁻¹"},{"enonce":"Vers où la variation du vecteur vitesse est-elle dirigée dans ce mouvement circulaire uniforme ?","aide":"Regarde la flèche oblique : de quel côté du cercle pointe-t-elle depuis le milieu de l’arc M1M3 ?","type":"choix","options":[{"id":"a","texte":"Dans le sens du mouvement, tangente au cercle"},{"id":"b","texte":"Vers l’extérieur, à l’opposé du centre"},{"id":"c","texte":"Nulle part : elle est égale au vecteur nul"},{"id":"d","texte":"Vers le centre du cercle décrit par la nacelle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"En M1, le vecteur vitesse est tangent au cercle et part de M1 : c’est la flèche **verticale** qui quitte M1."},{"cle":{"type":"zone","ids":["z5"]},"explication":"La variation Δv = v₃ − v₁ se trace de l’extrémité de v₁ à l’extrémité de v₃ : c’est la flèche **oblique**."},{"cle":{"type":"nombre","valeur":2.8,"tolerance":0.05},"affichage":"2,8 m·s⁻¹","explication":"70,7 unités ↔ 70,7 × 2,0 / 50 = 2,83 : Δv ≈ **2,8 m·s⁻¹**. Elle n’est pas nulle alors que la valeur de la vitesse ne change pas."},{"cle":{"type":"choix","ids":["d"]},"explication":"Entre M1 et M3, Δv pointe vers l’intérieur de la trajectoire : **vers le centre**. C’est aussi le sens de la somme des forces qui agissent sur la nacelle."}]$ex$::jsonb),
  ('1d74eec5-d615-5c6e-a540-bf3b0314550d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le wagon du train fantôme freine","competence":"raisonner","situation":"À la fête foraine, un wagon de train fantôme roule vers la droite puis freine avant le quai. Une caméra relève son abscisse toutes les τ = 0,50 s ; le schéma donne les directions possibles pour les forces.","documents":[{"id":"releves","type":"tableau","titre":"Positions du wagon","colonnes":["Position","M0","M1","M2","M3","M4"],"lignes":[["Abscisse x (m)","0","5,0","9,0","12,0","14,0"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"},{"id":"forces","type":"schema","titre":"Directions possibles pour la somme des forces","largeur":340,"hauteur":220,"elements":[{"forme":"rect","x":120,"y":90,"l":100,"h":40,"arrondi":8,"teinte":"gris","motif":"clair"},{"forme":"ligne","de":[170,110],"a":[255,110],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z1","zone":true},{"forme":"ligne","de":[170,110],"a":[85,110],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z2","zone":true},{"forme":"ligne","de":[170,110],"a":[170,30],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z3","zone":true},{"forme":"ligne","de":[170,110],"a":[170,190],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z4","zone":true},{"forme":"texte","x":290,"y":85,"texte":"sens du","ancre":"milieu","taille":"petit"},{"forme":"texte","x":290,"y":100,"texte":"mouvement →","ancre":"milieu","taille":"petit"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Calcule la valeur de la vitesse en M1 : v(M1) = M0M2 / (2τ).","aide":"M0M2 est la différence des abscisses de M2 et M0.","type":"nombre","unite":"m·s⁻¹"},{"enonce":"Calcule de même la valeur de la vitesse en M3.","aide":"Utilise M2M4 et la même durée 2τ.","type":"nombre","unite":"m·s⁻¹"},{"enonce":"De combien la valeur de la vitesse a-t-elle diminué entre M1 et M3 ?","aide":"Soustrais les deux vitesses calculées.","type":"nombre","unite":"m·s⁻¹"},{"enonce":"Touche la flèche qui indique le sens de la somme des forces appliquées au wagon pendant le freinage.","aide":"Le vecteur variation de vitesse a le même sens que la somme des forces. Dans quel sens la vitesse change-t-elle ?","type":"zone","document":"forces","multiple":false},{"enonce":"Si les forces appliquées au wagon se compensaient, que verrait-on sur les relevés ?","aide":"Si la somme des forces est nulle, le vecteur vitesse ne varie pas.","type":"choix","options":[{"id":"a","texte":"Des positions qui reviennent en arrière sans cesse"},{"id":"b","texte":"Des écarts de plus en plus grands entre positions"},{"id":"c","texte":"Des écarts de plus en plus petits entre positions"},{"id":"d","texte":"Des écarts constants entre deux positions successives"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9,"tolerance":0.05},"affichage":"9 m·s⁻¹","explication":"M0M2 = 9,0 − 0 = 9,0 m ; 2τ = 1,0 s ; v(M1) = 9,0 / 1,0 = **9,0 m·s⁻¹**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0.05},"affichage":"5 m·s⁻¹","explication":"M2M4 = 14,0 − 9,0 = 5,0 m ; v(M3) = 5,0 / 1,0 = **5,0 m·s⁻¹**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0.05},"affichage":"4 m·s⁻¹","explication":"9,0 − 5,0 = **4,0 m·s⁻¹**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La vitesse diminue : Δv est dirigée vers l’**arrière**, donc la somme des forces aussi (les freins l’emportent sur les autres forces horizontales)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Forces qui se compensent : vitesse constante, donc le wagon parcourrait des **distances égales** pendant des durées égales. Ici les écarts diminuent : elles ne se compensent pas."}]$ex$::jsonb),
  ('25e61fb2-54c0-5300-9f1d-92e9e9cf73ab'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un robot explorateur de 40 kg","competence":"lire-tableau","situation":"Une équipe prépare un petit robot-explorateur de 40 kg. Elle veut savoir quel poids il aura sur chaque astre visité. Le tableau donne la valeur g de la pesanteur à la surface de chaque astre.","documents":[{"id":"g","type":"tableau","titre":"Pesanteur à la surface de trois astres","colonnes":["Astre","Terre","Lune","Mars"],"lignes":[["g (N·kg⁻¹)","9,8","1,6","3,7"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche la case de l’astre où un objet est le plus léger à porter.","aide":"Le poids est proportionnel à g : cherche le plus petit g.","type":"zone","document":"g","multiple":false},{"enonce":"Quel est le poids du robot sur la Lune ?","aide":"Utilise P = m × g avec g lu dans le tableau.","type":"nombre","unite":"N"},{"enonce":"Quel est son poids sur Terre ?","aide":"Même relation, avec la valeur de g pour la Terre.","type":"nombre","unite":"N"},{"enonce":"Quelle est la masse du robot sur la Lune ?","aide":"La masse mesure la quantité de matière, pas l’attraction du lieu.","type":"choix","options":[{"id":"a","texte":"392 kg, la même valeur qu’en newtons"},{"id":"b","texte":"40 kg, la même que sur Terre"},{"id":"c","texte":"64 kg, car g y est plus petit"},{"id":"d","texte":"6,5 kg, car la Lune attire moins"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Le poids P = m × g est le plus faible là où g est le plus faible : **la Lune** (1,6 N·kg⁻¹)."},{"cle":{"type":"nombre","valeur":64,"tolerance":0.5},"affichage":"64 N","explication":"P = m × g = 40 kg × 1,6 N·kg⁻¹ = **64 N**."},{"cle":{"type":"nombre","valeur":392,"tolerance":0.5},"affichage":"392 N","explication":"P = 40 × 9,8 = **392 N**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La masse ne dépend pas du lieu : le robot garde ses **40 kg**. Seul son poids change."}]$ex$::jsonb),
  ('25e61fb2-54c0-5300-9f1d-92e9e9cf73ab'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le sac suspendu au dynamomètre","competence":"experimenter","situation":"Au CDI, Inès suspend son sac à un dynamomètre accroché à un support fixe. Le sac est immobile. Elle veut vérifier la masse du sac à partir de l’indication de l’appareil.","documents":[{"id":"sch","type":"schema","titre":"Le sac au bout du dynamomètre","largeur":340,"hauteur":262,"elements":[{"forme":"rect","x":120,"y":8,"l":100,"h":14,"teinte":"gris","motif":"plein"},{"forme":"ligne","de":[170,22],"a":[170,60],"epaisseur":2},{"forme":"rect","x":150,"y":60,"l":40,"h":70,"arrondi":6,"teinte":"gris","motif":"clair","id":"z1"},{"forme":"texte","x":170,"y":100,"texte":"24,5 N","ancre":"milieu","taille":"normal","gras":true},{"forme":"ligne","de":[170,130],"a":[170,150],"epaisseur":2},{"forme":"rect","x":135,"y":150,"l":70,"h":56,"arrondi":14,"teinte":"brun","motif":"clair"},{"forme":"texte","x":170,"y":183,"texte":"sac","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[170,178],"a":[170,252],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z2","zone":true},{"forme":"ligne","de":[170,140],"a":[170,66],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z3","zone":true},{"forme":"texte","x":60,"y":100,"texte":"dynamomètre","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[95,100],"a":[148,100],"teinte":"gris","style":"pointilles"}],"source":"Schéma écrit pour l’exercice ; g ≈ 9,8 N·kg⁻¹"}],"questions":[{"enonce":"Touche la flèche qui représente le poids du sac, c’est-à-dire l’action de la Terre sur lui.","aide":"Le poids est vertical et dirigé vers le bas.","type":"zone","document":"sch","multiple":false},{"enonce":"Classe chaque action exercée sur le sac : action de contact ou action à distance ?","aide":"Y a-t-il un contact matériel entre l’auteur de l’action et le sac ?","type":"categories","categories":[{"id":"c0","texte":"Action de contact"},{"id":"c1","texte":"Action à distance"}],"items":[{"id":"i0","texte":"La résistance de l’air sur le sac"},{"id":"i1","texte":"La force exercée par le crochet du dynamomètre"},{"id":"i2","texte":"Le poids du sac, dû à l’attraction de la Terre"},{"id":"i3","texte":"L’attraction d’un aimant posé près du sac"}]},{"enonce":"Le dynamomètre indique 24,5 N. Quelle est la masse du sac ? (g ≈ 9,8 N·kg⁻¹)","aide":"Le poids vaut P = m × g : isole la masse m.","type":"nombre","unite":"kg"},{"enonce":"Le sac tire vers le bas sur le crochet avec une force de 24,5 N. Que fait le crochet sur le sac ?","aide":"Principe des actions réciproques : même direction, même valeur, sens opposé.","type":"choix","options":[{"id":"a","texte":"Il exerce une force de 2,5 N, vers le haut"},{"id":"b","texte":"Il exerce une force de 24,5 N, vers le bas"},{"id":"c","texte":"Il n’exerce aucune force, le sac est immobile"},{"id":"d","texte":"Il exerce une force de 24,5 N, vers le haut"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le poids est vertical, vers le bas, appliqué au centre de gravité du sac : c’est la flèche du **bas**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Le fil, le crochet et l’air touchent le sac : **contact**. La pesanteur et l’aimant agissent sans toucher : **à distance**."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0.05},"affichage":"2,5 kg","explication":"Le sac est immobile : le dynamomètre mesure son poids. m = P / g = 24,5 / 9,8 = **2,5 kg**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Si A agit sur B, B agit sur A avec une force de même valeur et de **sens opposé** : **24,5 N vers le haut**."}]$ex$::jsonb),
  ('25e61fb2-54c0-5300-9f1d-92e9e9cf73ab'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un satellite de 500 kg autour de la Terre","competence":"modeliser","situation":"Un petit satellite d’observation de 500 kg tourne autour de la Terre à 600 km d’altitude. Des ingénieurs étudient la force de gravitation exercée par la Terre sur lui et comment elle change avec la distance.","documents":[{"id":"donnees","type":"tableau","titre":"Données","colonnes":["Grandeur","Valeur"],"lignes":[["Masse de la Terre","5,97 × 10²⁴ kg"],["Rayon de la Terre","6 371 km"],["Constante G","6,67 × 10⁻¹¹ N·m²·kg⁻²"],["Altitude du satellite","600 km"]],"enteteLignes":true,"source":"Valeurs arrondies"},{"id":"courbe","type":"graphique","forme":"courbe","titre":"Force exercée par la Terre sur le satellite","categories":["1 R","2 R","3 R","4 R"],"series":[{"nom":"Force","valeurs":[4.9,1.23,0.54,0.31],"teinte":"violet"}],"axeY":{"titre":"Force","unite":"kN","min":0,"max":6,"pas":1},"axeX":{"titre":"Distance au centre de la Terre (R = rayon terrestre)"},"valeurs":false,"source":"Calcul écrit pour l’exercice"}],"questions":[{"enonce":"Quelle est la distance d entre le satellite et le centre de la Terre ?","aide":"Le centre de la Terre est à un rayon terrestre sous la surface : ajoute l’altitude.","type":"nombre","unite":"km"},{"enonce":"Calcule la force de gravitation F = G × m(Terre) × m(satellite) / d² (convertis d en mètres). Donne F en kN, arrondie à 0,1 kN.","aide":"Convertis d en mètres (6,971 × 10⁶ m) avant de calculer.","type":"nombre","unite":"kN"},{"enonce":"Sur la courbe, touche la distance pour laquelle la force vaut environ 1,2 kN.","aide":"Repère 1,2 kN sur l’axe vertical, puis lis la distance sous le point.","type":"zone","document":"courbe","multiple":false},{"enonce":"Lis la force à 1 R et à 3 R : combien de fois la force est-elle plus petite à 3 R qu’à 1 R ?","aide":"Divise la valeur lue à 1 R par la valeur lue à 3 R.","type":"nombre"},{"enonce":"Quelle force le satellite exerce-t-il sur la Terre ?","aide":"Principe des actions réciproques.","type":"choix","options":[{"id":"a","texte":"La même valeur, 4,1 kN, mais de sens opposé"},{"id":"b","texte":"Une force de 4,1 kN dirigée dans le même sens"},{"id":"c","texte":"Une force 500 fois plus petite que celle de la Terre"},{"id":"d","texte":"Une force presque nulle car sa masse est faible"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":6971,"tolerance":0.5},"affichage":"6971 km","explication":"d = rayon + altitude = 6 371 + 600 = **6 971 km**."},{"cle":{"type":"nombre","valeur":4.1,"tolerance":0.05},"affichage":"4,1 kN","explication":"F = 6,67 × 10⁻¹¹ × 5,97 × 10²⁴ × 500 / (6,971 × 10⁶)² ≈ 4,1 × 10³ N, soit **4,1 kN**."},{"cle":{"type":"zone","ids":["k1"]},"explication":"À **2 R** la courbe vaut 1,23 kN, soit environ 1,2 kN."},{"cle":{"type":"nombre","valeur":9,"tolerance":0.5},"affichage":"9","explication":"4,9 / 0,54 ≈ 9 : à une distance triple, la force est divisée par 3² = **9**, car F varie en 1/d²."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les deux corps s’attirent avec des forces de **même valeur** et de sens opposés, même si les masses sont très différentes."}]$ex$::jsonb),
  ('10278a4d-480a-5704-863f-74e8302f6310'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Cinq observations dans la journée de Karim","competence":"analyser-document","situation":"Karim note cinq observations au cours de sa journée. Pour chacune, il veut savoir si les forces qui s’exercent sur le système se compensent ou non, en utilisant le principe d’inertie.","documents":[{"id":"obs","type":"tableau","titre":"Les observations de Karim","colonnes":["Système observé","Ce que Karim constate"],"lignes":[["Un livre posé sur son bureau","Il ne bouge pas"],["Un train sur une voie droite","Vitesse constante : 80 km/h"],["Une pierre lâchée sans vitesse","Elle va de plus en plus vite"],["Une voiture dans un rond-point","Vitesse constante en valeur, direction qui change"],["Un palet sur table à coussin d’air","Il glisse en ligne droite, sans changer de vitesse"]],"enteteLignes":true,"source":"Observations écrites pour l’exercice"}],"questions":[{"enonce":"Touche les deux observations où le vecteur vitesse varie.","aide":"Le vecteur vitesse varie si sa valeur ou sa direction change.","type":"zone","document":"obs","multiple":true},{"enonce":"Pour chaque système, les forces se compensent-elles ?","aide":"Vecteur vitesse constant : les forces se compensent. Vecteur vitesse qui varie : elles ne se compensent pas.","type":"categories","categories":[{"id":"c0","texte":"Les forces se compensent"},{"id":"c1","texte":"Les forces ne se compensent pas"}],"items":[{"id":"i0","texte":"Le livre posé sur le bureau"},{"id":"i1","texte":"Le train à vitesse constante en ligne droite"},{"id":"i2","texte":"La pierre qui tombe"},{"id":"i3","texte":"Le palet sur coussin d’air"},{"id":"i4","texte":"La voiture dans le rond-point"}]},{"enonce":"Pour entretenir le mouvement du train à vitesse constante en ligne droite, faut-il une force qui l’emporte sur les autres ?","aide":"Relis l’énoncé du principe d’inertie.","type":"choix","options":[{"id":"a","texte":"Non : les forces se compensent, il continue tout seul"},{"id":"b","texte":"Non : aucune force ne s’exerce alors sur le train"},{"id":"c","texte":"Oui : sans force vers l’avant, il s’arrêterait aussitôt"},{"id":"d","texte":"Oui : la force doit être plus grande que les frottements"}],"multiple":false}]}$ex$::jsonb,
