  ('10278a4d-480a-5704-863f-74e8302f6310'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La bille et la plume tombent dans deux tubes","competence":"experimenter","situation":"En classe, Louis lâche en même temps une bille et une plume dans deux tubes identiques : le tube A contient de l’air, dans le tube B on a fait le vide. Une caméra relève aussi la chute de la bille toutes les 0,10 s.","documents":[{"id":"bille","type":"tableau","titre":"Chute de la bille (tube A)","colonnes":["Instant (s)","0","0,10","0,20","0,30","0,40"],"lignes":[["Hauteur parcourue (cm)","0","4,9","19,6","44,1","78,4"]],"enteteLignes":true,"source":"Valeurs arrondies, écrites pour l’exercice"},{"id":"tubes","type":"schema","titre":"Les deux tubes à un même instant","largeur":340,"hauteur":258,"elements":[{"forme":"rect","x":40,"y":20,"l":90,"h":190,"arrondi":8,"teinte":"gris","motif":"clair"},{"forme":"rect","x":210,"y":20,"l":90,"h":190,"arrondi":8,"teinte":"gris","motif":"clair"},{"forme":"cercle","cx":70,"cy":150,"r":12,"teinte":"brun","motif":"plein","id":"z1"},{"forme":"ellipse","cx":100,"cy":90,"rx":14,"ry":6,"teinte":"ambre","motif":"plein","id":"z2","zone":true},{"forme":"cercle","cx":240,"cy":150,"r":12,"teinte":"brun","motif":"plein","id":"z3"},{"forme":"ellipse","cx":270,"cy":150,"rx":14,"ry":6,"teinte":"ambre","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":85,"y":228,"texte":"Tube A : air","ancre":"milieu","taille":"normal"},{"forme":"texte","x":255,"y":228,"texte":"Tube B : vide","ancre":"milieu","taille":"normal"},{"forme":"texte","x":170,"y":248,"texte":"Photo prise au même instant après le lâcher","ancre":"milieu","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Estime la vitesse de la bille à t = 0,20 s : divise la distance parcourue entre 0,10 s et 0,30 s par 0,20 s.","aide":"Distance entre les instants 0,10 s et 0,30 s : 44,1 − 4,9.","type":"nombre","unite":"cm·s⁻¹"},{"enonce":"Estime de la même façon la vitesse à t = 0,30 s. De combien a-t-elle augmenté en 0,10 s ?","aide":"Calcule v(0,30 s) avec les hauteurs à 0,20 s et 0,40 s, puis fais la différence.","type":"nombre","unite":"cm·s⁻¹"},{"enonce":"Touche la plume du tube où elle tombe moins vite que la bille.","aide":"Compare la hauteur de la plume à celle de la bille dans chaque tube.","type":"zone","document":"tubes","multiple":false},{"enonce":"Pourquoi la plume est-elle en retard dans l’air ?","aide":"Dans le vide, bille et plume tombent ensemble : qu’est-ce qui change dans l’air ?","type":"choix","options":[{"id":"a","texte":"La plume est attirée vers le haut par la paroi du tube"},{"id":"b","texte":"La plume est plus légère donc elle subit moins de pesanteur"},{"id":"c","texte":"La résistance de l’air agit beaucoup plus sur elle que sur la bille"},{"id":"d","texte":"La pesanteur ne s’exerce que sur les objets lourds de la bille"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":196,"tolerance":1},"affichage":"196 cm·s⁻¹","explication":"v ≈ (44,1 − 4,9) / 0,20 = 39,2 / 0,20 = **196 cm·s⁻¹**."},{"cle":{"type":"nombre","valeur":98,"tolerance":1},"affichage":"98 cm·s⁻¹","explication":"v(0,30 s) ≈ (78,4 − 19,6) / 0,20 = 294 cm·s⁻¹ ; 294 − 196 = **98 cm·s⁻¹** de plus en 0,10 s : la bille accélère de façon régulière."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Dans le tube d’air, la plume est restée en retard : **plume du tube A**. Dans le vide, elle suit la bille."},{"cle":{"type":"choix","ids":["c"]},"explication":"Dans le vide, plume et bille tombent ensemble (chute libre : seul le poids agit). Dans l’air, c’est la **résistance de l’air** qui sépare les deux."}]$ex$::jsonb),
  ('10278a4d-480a-5704-863f-74e8302f6310'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le saut en parachute de Salomé","competence":"raisonner","situation":"Salomé et son équipement pèsent 80 kg. Elle saute d’un avion, tombe, ouvre son parachute à 15 s puis atterrit. Un capteur enregistre la valeur de sa vitesse ; le schéma compare le poids et les frottements de l’air à trois moments.","documents":[{"id":"vit","type":"graphique","forme":"courbe","titre":"Vitesse de Salomé","categories":["0 s","5 s","10 s","15 s","20 s","25 s","30 s","35 s"],"series":[{"nom":"Vitesse","valeurs":[0,35,50,50,12,5,5,5],"teinte":"bleu"}],"axeY":{"titre":"Vitesse","unite":"m·s⁻¹","min":0,"max":60,"pas":10},"axeX":{"titre":"Temps"},"valeurs":false,"source":"Mesures simplifiées, écrites pour l’exercice"},{"id":"bilan","type":"schema","titre":"Bilan des forces à trois moments","largeur":340,"hauteur":240,"elements":[{"forme":"texte","x":60,"y":14,"texte":"Chute accélérée","ancre":"milieu","taille":"petit"},{"forme":"texte","x":170,"y":14,"texte":"Parachute, freinage","ancre":"milieu","taille":"petit"},{"forme":"texte","x":280,"y":14,"texte":"Vitesse constante","ancre":"milieu","taille":"petit"},{"forme":"cercle","cx":60,"cy":135,"r":8,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":170,"cy":135,"r":8,"teinte":"gris","motif":"plein"},{"forme":"cercle","cx":280,"cy":135,"r":8,"teinte":"gris","motif":"plein"},{"forme":"ligne","de":[60,135],"a":[60,205],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z1","zone":true},{"forme":"ligne","de":[60,135],"a":[60,105],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z2","zone":true},{"forme":"ligne","de":[170,135],"a":[170,205],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z3","zone":true},{"forme":"ligne","de":[170,135],"a":[170,30],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z4","zone":true},{"forme":"ligne","de":[280,135],"a":[280,205],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z5","zone":true},{"forme":"ligne","de":[280,135],"a":[280,65],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z6","zone":true},{"forme":"texte","x":170,"y":228,"texte":"Poids vers le bas, frottements de l’air vers le haut","ancre":"milieu","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois instants où Salomé, parachute ouvert, a une vitesse constante.","aide":"Cherche les points qui sont à la même hauteur et après l’ouverture du parachute.","type":"zone","document":"vit","multiple":true},{"enonce":"De combien la valeur de la vitesse a-t-elle diminué entre 15 s et 25 s ?","aide":"Lis la vitesse à 15 s et à 25 s.","type":"nombre","unite":"m·s⁻¹"},{"enonce":"Touche la flèche des frottements de l’air pendant la phase où Salomé ralentit.","aide":"Si elle ralentit, la somme des forces est dirigée vers le haut : quelle flèche doit être la plus longue ?","type":"zone","document":"bilan","multiple":false},{"enonce":"Une fois la vitesse constante (30 s), les forces se compensent. Quelle est la valeur de la force de frottement exercée par l’air ? (g ≈ 9,8 N·kg⁻¹)","aide":"Il faut d’abord calculer le poids de Salomé.","type":"nombre","unite":"N"},{"enonce":"Entre 0 s et 10 s, la vitesse augmente. Que peut-on en conclure ?","aide":"Que dit le principe d’inertie quand le vecteur vitesse varie ?","type":"choix","options":[{"id":"a","texte":"Aucune force ne s’exerce sur Salomé durant ce temps"},{"id":"b","texte":"Les frottements de l’air sont supérieurs à son poids"},{"id":"c","texte":"Les forces ne se compensent pas : le poids l’emporte"},{"id":"d","texte":"Les forces se compensent : elle est en chute libre"}],"multiple":false}]}$ex$::jsonb,
