  ('832cbafb-fb8a-5c07-90ff-6933a2096979'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Lou au concert du lycée","competence":"analyser-document","situation":"Lou assiste au concert de son lycée, assise à 34 m de la scène. Elle entend la guitare d’Hugo alors que celle-ci est loin d’elle. Le schéma montre la chaîne qui relie la guitare à son oreille.","documents":[{"id":"chaine","type":"chaine","titre":"De la guitare à l’oreille","disposition":"ligne","noeuds":[{"id":"z1","texte":"Corde de guitare","emoji":"🎸"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Oreille de Lou","emoji":"👂"}],"liens":[{"de":"z1","a":"z2","texte":"fait vibrer"},{"de":"z2","a":"z3","texte":"transmet à"}]},{"id":"celerites","type":"tableau","titre":"Célérité du son selon le milieu","colonnes":["Milieu","Air à 20 °C","Eau"],"lignes":[["Célérité (m·s⁻¹)","340","1 500"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche la source du son, l’objet qui vibre.","aide":"Un son naît d’un objet qui vibre.","type":"zone","document":"chaine","multiple":false},{"enonce":"Quel milieu matériel transmet la vibration de la guitare à l’oreille de Lou ? (un mot)","aide":"Lou et la scène sont dans une salle, pas dans l’eau.","type":"texte"},{"enonce":"Combien de temps le son met-il pour parcourir les 34 m jusqu’à Lou ?","aide":"Utilise v = d / Δt, donc Δt = d / v, avec la célérité dans l’air.","type":"nombre","unite":"s"},{"enonce":"Quand le son passe, que font les molécules d’air entre la scène et Lou ?","aide":"Le son transporte de l’énergie, pas de la matière.","type":"choix","options":[{"id":"a","texte":"Elles se déplacent dans le sens opposé à la source"},{"id":"b","texte":"Elles restent immobiles, seule l’énergie bouge"},{"id":"c","texte":"Elles oscillent autour de leur position d’équilibre"},{"id":"d","texte":"Elles voyagent de la scène jusqu’à l’oreille de Lou"}],"multiple":false}]}$ex$::jsonb,
