type":"choix","options":[{"id":"a","texte":"L’intensité, car la guitare joue toujours plus fort"},{"id":"b","texte":"La hauteur, car les deux notes n’ont pas la même fréquence"},{"id":"c","texte":"Le timbre, lié aux harmoniques présents dans le signal"},{"id":"d","texte":"La période, qui n’est pas la même pour les deux sons"}],"multiple":false}]}$ex$::jsonb,
