  ('bf193743-4add-5715-9623-983d7003215b'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un résistor et une ampoule de lampe de poche","competence":"experimenter","situation":"En TP, Karim trace la caractéristique de deux dipôles : un résistor (courbe bleue) et l’ampoule d’une lampe de poche (courbe violette). Il relève la tension à leurs bornes pour des intensités de 0 à 50 mA.","documents":[{"id":"carac","type":"graphique","forme":"courbe","titre":"Tension en fonction de l’intensité","categories":["0","10","20","30","40","50"],"series":[{"nom":"Résistor","valeurs":[0,1,2,3,4,5],"teinte":"bleu"},{"nom":"Ampoule","valeurs":[0,0.7,2,3.6,5.6,8],"teinte":"violet"}],"axeY":{"titre":"Tension","unite":"V","min":0,"max":8,"pas":1},"axeX":{"titre":"Intensité (mA)"},"valeurs":false,"source":"Mesures écrites pour l’exercice"}],"questions":[{"enonce":"Lequel de ces deux dipôles est un conducteur ohmique ?","aide":"Regarde l’allure de chaque courbe.","type":"choix","options":[{"id":"a","texte":"L’ampoule, dont la caractéristique est une courbe"},{"id":"b","texte":"Les deux, car les deux courbes montent"},{"id":"c","texte":"Aucun, car les deux passent par l’origine"},{"id":"d","texte":"Le résistor, dont la caractéristique est une droite"}],"multiple":false},{"enonce":"Quelle est la résistance du résistor ? (Utilise le point à 50 mA : 5 V.)","aide":"R = U / I avec I en ampères.","type":"nombre","unite":"Ω"},{"enonce":"Quelle est la résistance de l’ampoule à 50 mA ?","aide":"Lis la tension de l’ampoule à 50 mA, puis divise par l’intensité en ampères.","type":"nombre","unite":"Ω"},{"enonce":"À part l’origine, touche l’intensité pour laquelle les deux dipôles ont la même tension (donc la même résistance).","aide":"Cherche où les deux courbes se croisent.","type":"zone","document":"carac","multiple":false},{"enonce":"Pourquoi la résistance de l’ampoule augmente-t-elle quand l’intensité augmente ?","aide":"Que devient un filament parcouru par un courant ?","type":"choix","options":[{"id":"a","texte":"Le filament s’use et sa résistance diminue"},{"id":"b","texte":"Le filament s’échauffe et sa résistance augmente"},{"id":"c","texte":"Le résistor chauffe moins que l’ampoule"},{"id":"d","texte":"La pile se décharge et sa tension diminue"}],"multiple":false}]}$ex$::jsonb,
