rce primaire produit sa lumière ; un objet diffusant renvoie celle qu’il reçoit.","type":"categories","categories":[{"id":"c0","texte":"Source primaire"},{"id":"c1","texte":"Objet diffusant"}],"items":[{"id":"i0","texte":"La Lune"},{"id":"i1","texte":"Une page de cahier"},{"id":"i2","texte":"Un écran de téléphone allumé"},{"id":"i3","texte":"Une lampe de bureau allumée"},{"id":"i4","texte":"Le mur de la classe"},{"id":"i5","texte":"Le Soleil"}]},{"enonce":"Combien de temps la lumière du Soleil met-elle pour atteindre la Terre ? (t = d / c ; donne la durée en minutes, arrondie à 0,1 min.)","aide":"Calcule d’abord t en secondes, puis divise par 60.","type":"nombre","unite":"min"},{"enonce":"Combien de temps la lumière met-elle pour aller de la Lune à la Terre ? (arrondis à 0,1 s)","aide":"Même relation avec la distance Terre–Lune.","type":"nombre","unite":"s"}]}$ex$::jsonb,
