   $ex${"titre":"Un laser sur le miroir de la salle de bain","competence":"geometrie","situation":"Maya envoie un faisceau laser sur le miroir de la salle de bain. Elle représente le faisceau par un rayon et trace la normale au miroir au point d’incidence I.","documents":[{"id":"fig","type":"figure","titre":"Réflexion sur le miroir","cadre":{"xmin":0,"xmax":10,"ymin":0.6,"ymax":7.5},"quadrillage":false,"points":[{"id":"I","x":5,"y":2,"nom":"I","position":"se"},{"id":"S","x":1.644,"y":6,"nom":"S","position":"o"},{"id":"R","x":8.356,"y":6,"nom":"R","position":"e"},{"id":"N","x":5,"y":7,"nom":"N","position":"n"},{"id":"M1","x":0.5,"y":2,"cache":true},{"id":"M2","x":9.5,"y":2,"cache":true}],"segments":[{"id":"z1","de":"M1","a":"M2"},{"id":"z2","de":"I","a":"N","style":"pointilles"},{"id":"z3","de":"S","a":"I"},{"id":"z4","de":"I","a":"R"}],"angles":[{"id":"z5","sommet":"I","de":"N","a":"S","mesure":"40°"}],"source":"Figure écrite pour l’exercice"}],"questions":[{"enonce":"Touche le rayon réfléchi.","aide":"Le rayon incident arrive sur le miroir ; le rayon réfléchi en repart.","type":"zone","document":"fig","multiple":false},{"enonce":"Quelle est la valeur de l’angle de réflexion ?","aide":"Que dit la loi de la réflexion ?","type":"nombre","unite":"°"},{"enonce":"Quel angle fait le rayon réfléchi avec la surface du miroir ? (La normale est perpendiculaire au miroir.)","aide":"Les angles se mesurent par rapport à la normale ; entre la normale et le miroir il y a 90°.","type":"nombre","unite":"°"},{"enonce":"Le miroir est une surface très polie. Quel type de réflexion y a-t-il ?","aide":"Une surface polie renvoie un faisceau dans une seule direction.","type":"choix","options":[{"id":"a","texte":"Une absorption totale, car la surface est brillante"},{"id":"b","texte":"Une réflexion spéculaire, qui donne une image nette"},{"id":"c","texte":"Une réflexion diffuse, qui renvoie dans toutes les directions"},{"id":"d","texte":"Une réfraction, car la lumière entre dans le verre"}],"multiple":false}]}$ex$::jsonb,
