  ('c1b89b34-d967-591e-857b-13b0f4a1ebd3'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le rayon laser dans l’aquarium","competence":"experimenter","situation":"Léa éclaire la surface de l’eau d’un aquarium avec un laser. Elle mesure l’angle du rayon avec la normale, dans l’air (i₁) et dans l’eau (i₂), pour plusieurs inclinaisons. Elle essaie ensuite un autre liquide, plus épais.","documents":[{"id":"mes","type":"tableau","titre":"Mesures de Léa pour l’eau","colonnes":["Angle","Essai 1","Essai 2","Essai 3"],"lignes":[["i₁ dans l’air (°)","20","40","60"],["i₂ dans l’eau (°)","14,9","28,9","?"]],"enteteLignes":true,"source":"Valeurs arrondies"},{"id":"sch","type":"schema","titre":"L’essai 2 de Léa","largeur":340,"hauteur":210,"elements":[{"forme":"rect","x":30,"y":110,"l":280,"h":90,"teinte":"bleu","motif":"clair"},{"forme":"texte","x":105,"y":182,"texte":"eau (n = 1,33)","ancre":"milieu","taille":"petit"},{"forme":"texte","x":95,"y":50,"texte":"air (n = 1,00)","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[30,110],"a":[310,110],"epaisseur":2},{"forme":"ligne","de":[170,20],"a":[170,200],"style":"pointilles","teinte":"gris"},{"forme":"texte","x":185,"y":24,"texte":"normale","ancre":"debut","taille":"petit"},{"forme":"ligne","de":[102.9,30],"a":[170,110],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z1","zone":true},{"forme":"ligne","de":[170,110],"a":[214.2,190],"fleche":"fin","epaisseur":2,"teinte":"violet","id":"z2","zone":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche le rayon réfracté.","aide":"Le rayon réfracté est celui qui a changé de direction en traversant la surface.","type":"zone","document":"sch","multiple":false},{"enonce":"Avec la loi de Snell-Descartes n₁ × sin i₁ = n₂ × sin i₂, calcule i₂ pour l’essai 3 (arrondis à l’unité).","aide":"sin i₂ = (1,00 × sin 60°) / 1,33 ; utilise la fonction arcsin de la calculatrice.","type":"nombre","unite":"°"},{"enonce":"Avec l’essai 2, calcule l’indice n de l’eau : n = sin i₁ / sin i₂ (arrondis au centième, air : n = 1,00).","aide":"Divise sin 40° par sin 28,9°.","type":"nombre"},{"enonce":"Quand le rayon passe de l’air à l’eau, comment se comporte-t-il ?","aide":"Compare i₂ à i₁ dans le tableau.","type":"choix","options":[{"id":"a","texte":"Il se réfléchit totalement dès que i₁ dépasse 30°"},{"id":"b","texte":"Il se rapproche de la normale, car l’eau est plus réfringente"},{"id":"c","texte":"Il ne change pas de direction, car i₁ est petit"},{"id":"d","texte":"Il s’écarte de la normale, car l’eau est plus dense"}],"multiple":false},{"enonce":"Dans le liquide épais, Léa mesure i₁ = 60° et i₂ = 35°. Quel est son indice n ? (arrondis au centième)","aide":"n × sin 35° = 1,00 × sin 60°.","type":"nombre"}]}$ex$::jsonb,
