  ('c1b89b34-d967-591e-857b-13b0f4a1ebd3'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Sous l’eau, la lampe de Nina et la fibre optique","competence":"raisonner","situation":"Nina plonge dans une piscine avec une lampe étanche et l’oriente vers la surface. Elle fait varier l’angle d’incidence dans l’eau. Plus tard, elle découvre que le même phénomène guide la lumière dans une fibre optique.","documents":[{"id":"mes","type":"tableau","titre":"Lumière allant de l’eau vers l’air","colonnes":["Mesure","Essai 1","Essai 2","Essai 3","Essai 4"],"lignes":[["Angle d’incidence i₁ dans l’eau","30°","45°","50°","60°"],["Rayon réfracté dans l’air","i₂ = 42°","i₂ = 70°","aucun","aucun"]],"enteteLignes":true,"source":"Valeurs arrondies, n(eau) = 1,33"},{"id":"fibre","type":"schema","titre":"Un rayon dans une fibre optique","largeur":340,"hauteur":205,"elements":[{"forme":"rect","x":10,"y":80,"l":320,"h":60,"teinte":"ciel","motif":"clair"},{"forme":"texte","x":170,"y":160,"texte":"cœur de la fibre (verre)","ancre":"milieu","taille":"petit"},{"forme":"texte","x":170,"y":66,"texte":"gaine","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[10,110],"a":[70,80],"teinte":"corail","epaisseur":2},{"forme":"ligne","de":[70,80],"a":[130,140],"teinte":"corail","epaisseur":2},{"forme":"ligne","de":[130,140],"a":[190,80],"teinte":"corail","epaisseur":2},{"forme":"ligne","de":[190,80],"a":[250,140],"teinte":"corail","epaisseur":2},{"forme":"ligne","de":[250,140],"a":[320,100],"fleche":"fin","epaisseur":2,"teinte":"corail"},{"forme":"cercle","cx":70,"cy":80,"r":7,"teinte":"violet","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":130,"cy":140,"r":7,"teinte":"violet","motif":"plein","id":"z2","zone":true},{"forme":"cercle","cx":190,"cy":80,"r":7,"teinte":"violet","motif":"plein","id":"z3","zone":true},{"forme":"cercle","cx":250,"cy":140,"r":7,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"cercle","cx":170,"cy":110,"r":7,"teinte":"violet","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":170,"y":196,"texte":"Angles exagérés pour la lisibilité","ancre":"milieu","taille":"petit","italique":true}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Vérifie l’essai 1 : calcule i₂ avec 1,33 × sin 30° = 1,00 × sin i₂ (arrondis à l’unité).","aide":"sin i₂ = 1,33 × sin 30°, puis arcsin.","type":"nombre","unite":"°"},{"enonce":"Touche le premier essai (par angle croissant) pour lequel il n’y a plus aucun rayon réfracté.","aide":"Cherche la case « aucun » dans la deuxième ligne, puis lis l’angle au-dessus.","type":"zone","document":"mes","multiple":false},{"enonce":"L’angle limite θ vérifie 1,33 × sin θ = 1,00 × sin 90°. Calcule-le (arrondi à l’unité).","aide":"sin θ = 1 / 1,33 ; utilise arcsin.","type":"nombre","unite":"°"},{"enonce":"Touche tous les points où le rayon subit une réflexion totale contre la gaine.","aide":"Cherche les points où le rayon change de direction contre la paroi.","type":"zone","document":"fibre","multiple":true},{"enonce":"Pourquoi la lumière reste-t-elle guidée dans la fibre sur des kilomètres ?","aide":"Pense à ce que fait un rayon qui dépasse l’angle limite.","type":"choix","options":[{"id":"a","texte":"Elle subit des réflexions totales successives"},{"id":"b","texte":"Elle est réfractée à chaque fois dans la gaine"},{"id":"c","texte":"Elle est absorbée puis réémise par le verre"},{"id":"d","texte":"Elle se disperse comme dans un prisme à la sortie"}],"multiple":false}]}$ex$::jsonb,
