},{"forme":"ligne","de":[220,214],"a":[220,224]},{"forme":"texte","x":220,"y":238,"texte":"8","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[250,214],"a":[250,224]},{"forme":"texte","x":250,"y":238,"texte":"10","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[100,219],"a":[250,219]},{"forme":"texte","x":300,"y":238,"texte":"cm","ancre":"milieu","taille":"petit"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche le foyer image F′, le point où se rassemblent les rayons.","aide":"C’est le point de convergence des rayons parallèles à l’axe.","type":"zone","document":"sch","multiple":false},{"enonce":"Lis sur la graduation la distance focale f′ de la lentille, c’est-à-dire la distance OF′.","aide":"Cherche la graduation située sous le point F′.","type":"nombre","unite":"cm"},{"enonce":"Calcule la vergence de la lentille : C = 1 / f′, avec f′ en mètres.","aide":"Convertis 10 cm en 0,10 m.","type":"nombre","unite":"δ"},{"enonce":"Une autre lentille a une vergence de 5 δ. Quelle est sa distance focale, en cm ?","aide":"f′ = 1 / C, en mètres, puis convertis.","type":"nombre","unite":"cm"},{"enonce":"Comparée à la lentille de 10 δ, la lentille de 5 δ est :","aide":"Compare les distances focales : 10 cm et 20 cm.","type":"choix","options":[{"id":"a","texte":"Divergente, car sa vergence est plus petite"},{"id":"b","texte":"Aussi convergente, mais plus épaisse au centre"},{"id":"c","texte":"Moins convergente, avec un foyer plus éloigné de la lentille"},{"id":"d","texte":"Plus convergente, avec un foyer plus proche de la lentille"}],"multiple":false}]}$ex$::jsonb,
