stallin.","type":"zone","document":"oeil","multiple":false},{"enonce":"Quel est le défaut de vision d’Aya ?","aide":"Compare la position de l’image à celle de la rétine.","type":"choix","options":[{"id":"a","texte":"L’hypermétropie : l’image se forme derrière la rétine"},{"id":"b","texte":"La myopie : l’image se forme en avant de la rétine"},{"id":"c","texte":"Aucun : l’image se forme bien sur la rétine"},{"id":"d","texte":"La presbytie : le cristallin est devenu moins souple"}],"multiple":false},{"enonce":"Quel type de lentille corrige ce défaut, comme le dit l’ordonnance ?","aide":"Il faut éloigner le point où se forment les images : lentille divergente.","type":"choix","options":[{"id":"a","texte":"Une lentille convergente, de vergence négative"},{"id":"b","texte":"Une lentille convergente, de vergence positive"},{"id":"c","texte":"Une lentille divergente, de vergence négative"},{"id":"d","texte":"Une lentille divergente, de vergence positive"}],"multiple":false},{"enonce":"Quelle est la valeur absolue de la distance focale du verre de l’œil droit ? (|f′| = 1 / |C|, en cm)","aide":"Prends la valeur absolue de la vergence : 2,5 δ.","type":"nombre","unite":"cm"},{"enonce":"Quelle est la valeur absolue de la distance focale du verre de l’œil gauche, en cm ?","aide":"Même calcul avec 2,0 δ.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
