  ('997b009c-d4b0-5c4e-a327-61445a21fadd'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Thomas observe un timbre à la loupe","competence":"lire-tableau","situation":"Thomas déplace un timbre devant une lentille convergente de distance focale 10 cm. Dans trois essais, il note où se trouve l’objet (OA) et où se forme l’image (OA′), et s’il peut la recueillir sur un écran.","documents":[{"id":"essais","type":"tableau","titre":"Les trois essais de Thomas","colonnes":["Mesure","Essai 1","Essai 2","Essai 3"],"lignes":[["OA (cm)","−30","−15","−5"],["OA′ (cm)","15","30","−10"],["Image recueillie sur un écran ?","oui","oui","non"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’essai où l’image est virtuelle : on ne peut pas la recueillir sur un écran.","aide":"Une image virtuelle ne se projette pas ; regarde la dernière ligne.","type":"zone","document":"essais","multiple":false},{"enonce":"Calcule le grandissement de l’essai 1 : γ = OA′ / OA.","aide":"Divise 15 par −30 (garde le signe).","type":"nombre"},{"enonce":"Calcule le grandissement de l’essai 3.","aide":"Divise −10 par −5.","type":"nombre"},{"enonce":"Dans quel essai Thomas utilise-t-il la lentille comme une loupe ?","aide":"Une loupe donne une image virtuelle, droite et agrandie.","type":"choix","options":[{"id":"a","texte":"Dans l’essai 3, objet entre la lentille et le foyer"},{"id":"b","texte":"Dans l’essai 1, objet très loin de la lentille"},{"id":"c","texte":"Dans l’essai 2, objet entre le foyer et 2f′"},{"id":"d","texte":"Dans les trois, car la lentille est convergente"}],"multiple":false}]}$ex$::jsonb,
