  ('997b009c-d4b0-5c4e-a327-61445a21fadd'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"L’image du timbre à travers la lentille","competence":"geometrie","situation":"Salomé étudie un objet AB de 1,5 cm de haut placé à 3 cm d’une lentille convergente de distance focale 2 cm. Elle a tracé deux rayons : le rayon parallèle à l’axe, qui repart par F′, et le rayon passant par le centre optique O. Un carreau mesure 1 cm.","documents":[{"id":"fig","type":"figure","titre":"Construction de l’image","cadre":{"xmin":-4,"xmax":7,"ymin":-4,"ymax":3},"quadrillage":true,"points":[{"id":"A","x":-3,"y":0,"nom":"A","position":"so"},{"id":"B","x":-3,"y":1.5,"nom":"B","position":"no"},{"id":"O","x":0,"y":0,"nom":"O","position":"se"},{"id":"F","x":-2,"y":0,"nom":"F","position":"so"},{"id":"Fp","x":2,"y":0,"nom":"F′","position":"se"},{"id":"Ap","x":6,"y":0,"nom":"A′","position":"no"},{"id":"Bp","x":6,"y":-3,"nom":"B′","position":"se"},{"id":"L1","x":0,"y":2.6,"cache":true},{"id":"L2","x":0,"y":-3.6,"cache":true},{"id":"H","x":0,"y":1.5,"cache":true},{"id":"X1","x":-4,"y":0,"cache":true},{"id":"X2","x":7,"y":0,"cache":true}],"segments":[{"id":"z1","de":"X1","a":"X2","style":"pointilles"},{"id":"z2","de":"L1","a":"L2"},{"id":"z3","de":"A","a":"B","teinte":"violet"},{"id":"z4","de":"Ap","a":"Bp","teinte":"violet"},{"id":"z5","de":"B","a":"H","teinte":"corail"},{"id":"z6","de":"H","a":"Bp","teinte":"corail"},{"id":"z7","de":"B","a":"Bp","teinte":"corail"}],"source":"Construction écrite pour l’exercice"}],"questions":[{"enonce":"Touche l’image A′B′ de l’objet.","aide":"L’image se forme là où les deux rayons se croisent.","type":"zone","document":"fig","multiple":false},{"enonce":"Calcule la position de l’image avec 1/OA′ − 1/OA = 1/OF′ (OA = −3 cm, OF′ = 2 cm).","aide":"Ici 1/OA′ = 1/OF′ + 1/OA = 1/2 + 1/(−3).","type":"nombre","unite":"cm"},{"enonce":"Calcule le grandissement γ = OA′ / OA.","aide":"Garde le signe de OA (négatif).","type":"nombre"},{"enonce":"Quelle est la hauteur de l’image A′B′ ?","aide":"Hauteur de l’image = |γ| × hauteur de l’objet.","type":"nombre","unite":"cm"},{"enonce":"Quelle est la nature de l’image A′B′ ?","aide":"L’objet est au-delà du foyer objet ; γ est négatif et |γ| > 1.","type":"choix","options":[{"id":"a","texte":"Réelle, renversée et agrandie"},{"id":"b","texte":"Virtuelle, droite et agrandie"},{"id":"c","texte":"Virtuelle, renversée et agrandie"},{"id":"d","texte":"Réelle, renversée et plus petite"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"Les deux rayons se coupent en B′ : l’image est le segment **A′B′**, sous l’axe."},{"cle":{"type":"nombre","valeur":6,"tolerance":0.05},"affichage":"6 cm","explication":"1/OA′ = 1/2 − 1/3 = 1/6 donc OA′ = **6 cm** : cela correspond à ce qu’on lit sur la figure."},{"cle":{"type":"nombre","valeur":-2,"tolerance":0.02},"affichage":"−2","explication":"γ = 6 / (−3) = **−2** : l’image est renversée et deux fois plus grande."},{"cle":{"type":"nombre","valeur":3,"tolerance":0.05},"affichage":"3 cm","explication":"|γ| × AB = 2 × 1,5 = **3,0 cm** : on la lit aussi sur la figure."},{"cle":{"type":"choix","ids":["a"]},"explication":"Objet au-delà de F : image **réelle** (elle se projette sur un écran), γ < 0 donc **renversée**, |γ| = 2 donc **agrandie**."}]$ex$::jsonb),
  ('997b009c-d4b0-5c4e-a327-61445a21fadd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le vidéoprojecteur de Léo","competence":"modeliser","situation":"Léo construit un vidéoprojecteur avec une lentille convergente de distance focale 10 cm et une diapositive de 2,0 cm de haut, éclairée par une lampe. Il règle la distance diapositive-lentille pour que l’image se forme nette sur le mur. Les distances sont des mesures algébriques depuis O.","documents":[{"id":"sch","type":"schema","titre":"Le montage","largeur":340,"hauteur":230,"elements":[{"forme":"rect","x":10,"y":80,"l":40,"h":60,"arrondi":6,"teinte":"ambre","motif":"clair"},{"forme":"texte","x":30,"y":160,"texte":"lampe","ancre":"milieu","taille":"petit"},{"forme":"rect","x":70,"y":85,"l":8,"h":50,"teinte":"ciel","motif":"plein","id":"z1","zone":true},{"forme":"texte","x":74,"y":160,"texte":"diapositive","ancre":"milieu","taille":"petit"},{"forme":"chemin","d":"M 140 70 Q 165 110 140 150 Q 115 110 140 70 Z","teinte":"ciel","motif":"clair","id":"z2","zone":true},{"forme":"texte","x":140,"y":172,"texte":"lentille","ancre":"milieu","taille":"petit"},{"forme":"rect","x":300,"y":30,"l":10,"h":160,"teinte":"gris","motif":"clair","id":"z3","zone":true},{"forme":"texte","x":300,"y":205,"texte":"mur","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[50,110],"a":[300,110],"style":"pointilles","teinte":"gris"}],"source":"Schéma écrit pour l’exercice, hors échelle"},{"id":"regl","type":"tableau","titre":"Trois réglages","colonnes":["Mesure","Réglage 1","Réglage 2","Réglage 3"],"lignes":[["Diapositive : OA (cm)","−15","−12","−11"],["Mur : OA′ (cm)","30","?","110"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’objet dont la lentille donne une image sur le mur.","aide":"L’objet est ce qu’on éclaire, devant la lentille.","type":"zone","document":"sch","multiple":false},{"enonce":"Pour le réglage 2, calcule la distance OA′ du mur : 1/OA′ = 1/OF′ + 1/OA.","aide":"1/OA′ = 1/10 + 1/(−12) ; calcule avec des fractions de même dénominateur.","type":"nombre","unite":"cm"},{"enonce":"Calcule le grandissement du réglage 2 : γ = OA′ / OA.","aide":"Divise 60 par −12.","type":"nombre"},{"enonce":"Quelle est la hauteur de l’image sur le mur, avec ce réglage ?","aide":"Hauteur de l’image = |γ| × hauteur de la diapositive.","type":"nombre","unite":"cm"},{"enonce":"Touche le réglage qui donne la plus grande image sur le mur.","aide":"Le grandissement est le rapport OA′/OA : compare les trois réglages.","type":"zone","document":"regl","multiple":false}]}$ex$::jsonb,
