  ('94c8df39-d7f9-5d49-a14f-2309759f8404'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Trois envies, un seul samedi après-midi","competence":"lire-tableau","situation":"Maya a 12 € d’argent de poche et un seul samedi après-midi libre : elle ne peut faire qu’une sortie. Elle a noté trois envies de 0 à 10.","documents":[{"id":"envies","type":"tableau","titre":"Les trois envies de Maya","source":"Prix et notes imaginés pour l’exercice.","colonnes":["Activité","Prix","Note de Maya (sur 10)"],"lignes":[["Cinéma","9 €",8],["Bowling","12 €",9],["Patinoire","8 €",6]],"enteteLignes":true}],"questions":[{"enonce":"Touche le prix de la seule activité qui épuise à elle seule tout le budget de Maya.","aide":"Compare le prix de chaque activité aux 12 € dont Maya dispose.","type":"zone","document":"envies","multiple":false},{"enonce":"Maya rêve de faire le cinéma ET la patinoire. De combien d’euros dépasserait-elle son budget ?","aide":"Additionne les deux prix, puis retire les 12 € disponibles.","type":"nombre","unite":"€"},{"enonce":"Maya choisit le bowling. Quel est son coût d’opportunité ?","aide":"Le coût d’opportunité, c’est ce qu’on abandonne en faisant un choix, pas la somme qu’on paie.","type":"choix","options":[{"id":"a","texte":"Aucun : son budget suffit pour le bowling"},{"id":"b","texte":"La note de 9 sur 10 qu’elle donne au bowling"},{"id":"c","texte":"Les 12 € qu’elle dépense au bowling"},{"id":"d","texte":"Le cinéma et la patinoire, auxquels elle renonce"}],"multiple":false},{"enonce":"Associe chaque phrase à la notion d’économie qu’elle illustre.","aide":"Une phrase parle de limites, une autre de renoncement, la dernière de la personne qui consomme.","type":"association","gauche":[{"id":"g0","texte":"Maya n’a que 12 € pour trois envies"},{"id":"g1","texte":"En allant au bowling, elle ne fera ni cinéma ni patinoire"},{"id":"g2","texte":"Maya dépense son argent de poche et choisit ses loisirs"}],"droite":[{"id":"d0","texte":"Le coût d’opportunité"},{"id":"d1","texte":"Un ménage (agent économique)"},{"id":"d2","texte":"La rareté"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le bowling coûte **12 €** : c’est exactement son budget. Les deux autres activités laisseraient quelques euros."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 €","explication":"9 + 8 = 17 €, et 17 − 12 = **5 €** de trop. Ses besoins dépassent ses ressources : c’est la **rareté**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le coût d’opportunité est **ce à quoi on renonce** : ici, les autres sorties possibles. Les 12 € sont le prix payé, pas ce dont on se prive."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"La **rareté** est le manque de ressources face aux besoins ; le **coût d’opportunité** est le renoncement lié au choix ; Maya, qui consomme, est un **ménage**."}]$ex$::jsonb),
  ('94c8df39-d7f9-5d49-a14f-2309759f8404'::uuid, 2, 2, 10, 35, 4,
