  ('466c1452-b017-5929-8f9b-3efc5e95fb28'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Aldoria et Borvia : combien ça fait en trente ans ?","competence":"calculer","situation":"Deux pays imaginaires, Aldoria et Borvia, ont des rythmes de croissance différents. Une économiste calcule leur croissance et se demande si Borvia, l’an dernier, est tombée en récession.","documents":[{"id":"ans","type":"tableau","titre":"Le PIB en volume de deux pays","source":"Chiffres imaginés pour l’exercice.","colonnes":["Pays","PIB 2022 (milliards d’euros)","PIB 2023 (milliards d’euros)"],"lignes":[["Aldoria",1000,1020],["Borvia",800,840]],"enteteLignes":true},{"id":"trim","type":"tableau","titre":"Borvia en 2024 : variation du PIB en volume, trimestre par trimestre","source":"Chiffres imaginés pour l’exercice.","colonnes":["","T1","T2","T3","T4"],"lignes":[["Variation du PIB (%)","+0,4","−0,3","−0,5","+0,2"]],"enteteLignes":true}],"questions":[{"enonce":"Quel est le taux de croissance d’Aldoria en 2023, en % ?","aide":"Taux = (PIB 2023 − PIB 2022) ÷ PIB 2022.","type":"nombre","unite":"%"},{"enonce":"Si Aldoria garde ce rythme chaque année, en combien d’années sa production double-t-elle environ ?","aide":"À 2 % par an, les intérêts composés font doubler la production en un peu plus de trois décennies.","type":"nombre","unite":"ans"},{"enonce":"Borvia croît de 5 % par an, comme la France des Trente Glorieuses. Par combien environ sa production est-elle multipliée en 30 ans (arrondi au dixième) ?","aide":"Multiplie par 1,05 trente fois, ou utilise la touche puissance de ta calculatrice : 1,05 puissance 30.","type":"nombre"},{"enonce":"Touche les deux trimestres consécutifs qui permettent de parler de récession.","aide":"Cherche deux reculs du PIB qui se suivent.","type":"zone","document":"trim","multiple":true},{"enonce":"Le recul de Borvia est-il une récession ou une dépression ?","aide":"Une dépression est un recul durable et profond, comme après 1929.","type":"choix","options":[{"id":"a","texte":"Une récession : le recul est faible et bref"},{"id":"b","texte":"Une expansion : le PIB a augmenté en T4"},{"id":"c","texte":"Une dépression : le PIB a reculé deux trimestres"},{"id":"d","texte":"Ni l’une ni l’autre : le PIB a augmenté en T1"}],"multiple":false}]}$ex$::jsonb,
