  ('466c1452-b017-5929-8f9b-3efc5e95fb28'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Une croissance inégale : de Londres à Pékin","competence":"lire-carte","situation":"Un professeur d’économie montre sur une carte d’où est partie la croissance moderne et où elle a gagné du terrain. Il y ajoute les rythmes d’un pays ancien industrialisé.","documents":[{"id":"carte","type":"carte","fond":"monde","titre":"Quatre repères sur la carte","cadrage":[-12,5,150,62],"lieux":[{"id":"z1","lieu":"manchester","symbole":"lettre","lettre":"A","teinte":"encre"},{"id":"z2","lieu":"tokyo","symbole":"lettre","lettre":"B","teinte":"encre"},{"id":"z3","lieu":"pekin","symbole":"lettre","lettre":"C","teinte":"encre"},{"id":"z4","lieu":"delhi","symbole":"lettre","lettre":"D","teinte":"encre"}]},{"id":"rythmes","type":"tableau","titre":"Croissance annuelle moyenne d’un pays ancien industrialisé","source":"Chiffres arrondis, imaginés pour l’exercice.","colonnes":["Période","Croissance annuelle moyenne (%)"],"lignes":[["1945-1975",5],["1975-2008",2],["2008-2020",0.8]],"enteteLignes":true}],"questions":[{"enonce":"Touche le repère situé dans le pays où démarre la révolution industrielle, à la fin du XVIIIe siècle.","aide":"Il s’agit d’une île située au nord-ouest de la France.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le repère situé dans le pays dont la croissance a décollé à la fin du XIXe siècle, puis repris après 1945.","aide":"Ce pays d’Asie est une île à l’est du continent.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les deux repères situés dans les deux pays les plus peuplés du monde, devenus émergents.","aide":"Ce sont deux géants d’Asie dont la croissance a décollé dans les dernières décennies.","type":"zone","document":"carte","multiple":true},{"enonce":"De combien de points le rythme de croissance a-t-il baissé entre 1945-1975 et 1975-2008 ?","aide":"Soustrais les deux pourcentages du tableau : on obtient des points de pourcentage.","type":"nombre","unite":"points"},{"enonce":"Que montrent ensemble la carte et le tableau ?","aide":"Le cours résume la croissance en trois mots : récente, inégale, irrégulière.","type":"choix","options":[{"id":"a","texte":"Une croissance continue et identique dans tous les pays depuis 1800 environ"},{"id":"b","texte":"Une croissance récente, inégale selon les régions, irrégulière dans le temps"},{"id":"c","texte":"Une croissance partie de Chine, arrivée en Europe seulement après 1975"},{"id":"d","texte":"Une croissance qui ne dépend que de l’inflation propre à chaque pays"}],"multiple":false},{"enonce":"Associe chaque terme à sa définition.","aide":"Les trois termes décrivent des mouvements irréguliers de la production.","type":"association","gauche":[{"id":"g0","texte":"Expansion"},{"id":"g1","texte":"Récession"},{"id":"g2","texte":"Dépression"}],"droite":[{"id":"d0","texte":"Une hausse de la production de courte durée"},{"id":"d1","texte":"Un recul durable et profond, comme après 1929"},{"id":"d2","texte":"Un recul du PIB pendant au moins deux trimestres consécutifs"}]}]}$ex$::jsonb,
