lle humaine : pétrole, gaz, métaux.","type":"categories","categories":[{"id":"c0","texte":"Renouvelable"},{"id":"c1","texte":"Non renouvelable"}],"items":[{"id":"i0","texte":"Le cuivre des moteurs"},{"id":"i1","texte":"Le pétrole du gazole"},{"id":"i2","texte":"Les poissons de la baie"},{"id":"i3","texte":"Le bois des forêts"}]}]}$ex$::jsonb,
