  ('1e67895e-ac53-50df-bed3-8949b08ce213'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Une usine, une rivière : qui paie la pollution ?","competence":"observer-schema","situation":"Une usine rejette des polluants dans une rivière. Des pêcheurs voient leurs prises baisser et la commune doit dépolluer l’eau. Un économiste chiffre ce qui n’apparaît pas sur la facture de l’usine.","documents":[{"id":"schema","type":"schema","titre":"La rivière et ceux qui l’utilisent","source":"Schéma imaginé pour l’exercice.","largeur":340,"hauteur":250,"elements":[{"forme":"polygone","points":[[0,120],[340,120],[340,165],[0,165]],"teinte":"bleu","motif":"clair","id":"z1","zone":true},{"forme":"texte","x":300,"y":148,"texte":"Rivière","taille":"petit","italique":true},{"forme":"emoji","x":70,"y":55,"emoji":"🏭","taille":44,"id":"z2","zone":true},{"forme":"texte","x":70,"y":95,"texte":"Usine","taille":"petit"},{"forme":"ligne","de":[70,103],"a":[70,135],"fleche":"fin","teinte":"corail"},{"forme":"texte","x":80,"y":112,"texte":"rejets","taille":"petit","ancre":"debut"},{"forme":"emoji","x":250,"y":55,"emoji":"🎣","taille":40,"id":"z3","zone":true},{"forme":"texte","x":250,"y":95,"texte":"Pêcheurs","taille":"petit"},{"forme":"emoji","x":170,"y":195,"emoji":"🏘️","taille":40,"id":"z4","zone":true},{"forme":"texte","x":170,"y":232,"texte":"Commune","taille":"petit"},{"forme":"ligne","de":[170,168],"a":[170,180],"fleche":"fin","teinte":"encre"}]},{"id":"couts","type":"tableau","titre":"Une tonne de produit","source":"Chiffres imaginés pour l’exercice.","colonnes":["Poste","Montant par tonne (€)"],"lignes":[["Prix de vente",70],["Coût de production payé par l’usine",50],["Dégâts à la rivière payés par les pêcheurs et la commune",30]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’acteur qui produit la pollution.","aide":"Suis la flèche « rejets » jusqu’à son point de départ.","type":"zone","document":"schema","multiple":false},{"enonce":"Touche les deux acteurs qui subissent les dégâts sans les avoir causés.","aide":"Qui perd des prises ? Qui doit dépolluer l’eau ?","type":"zone","document":"schema","multiple":true},{"enonce":"Quel est le coût réel d’une tonne pour la société (production + dégâts), en euros ?","aide":"Additionne le coût payé par l’usine et les dégâts payés par les autres.","type":"nombre","unite":"€"},{"enonce":"Le prix de vente est de 70 € alors que le coût réel est de 80 €. Que peut-on dire de ce prix et de la production ?","aide":"Compare le prix de vente au coût réel pour la société.","type":"choix","options":[{"id":"a","texte":"Le prix est trop bas : la quantité produite est trop élevée"},{"id":"b","texte":"Le prix est trop haut : la quantité produite est trop faible"},{"id":"c","texte":"Le prix est trop bas : la production devrait rester au même niveau"},{"id":"d","texte":"Le prix est juste : le marché a bien tout compté"}],"multiple":false},{"enonce":"Selon le principe pollueur-payeur, quelle taxe par tonne ferait payer à l’usine le dommage causé, en euros ?","aide":"Le pollueur doit supporter le coût de la pollution qu’il cause.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est l’**usine** qui rejette les polluants dans la rivière."},{"cle":{"type":"zone","ids":["z3","z4"]},"explication":"Les **pêcheurs** (prises en baisse) et la **commune** (dépollution) supportent un coût qu’ils n’ont pas décidé : c’est une externalité négative."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 €","explication":"50 + 30 = **80 €** par tonne, alors que l’usine ne paie que 50 €."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un prix qui ne compte pas la pollution **ment sur ce que coûte le produit** : il est trop bas, donc on en produit et consomme trop."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 €","explication":"Une taxe de **30 € par tonne** ferait payer à l’usine le dommage subi par les autres : le prix intégrerait alors la pollution."}]$ex$::jsonb),
  ('1e67895e-ac53-50df-bed3-8949b08ce213'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Valmont cherche à réduire son CO₂ : mesures et points de vue","competence":"argumenter","situation":"La ville imaginaire de Valmont étudie cinq mesures contre ses émissions de CO₂. Au conseil, trois habitants défendent des visions différentes de la croissance et de l’écologie.","documents":[{"id":"mesures","type":"tableau","titre":"Cinq mesures étudiées par la ville","source":"Mesures imaginées pour l’exercice.","colonnes":["N°","Mesure"],"lignes":[[1,"Interdire les chaudières au fioul neuves"],[2,"Faire payer 50 € par tonne de CO₂ émise"],[3,"Plafonner à 1 000 tonnes les émissions de cinq usines, avec des droits d’émission échangeables"],[4,"Verser 2 000 € à toute personne qui installe une pompe à chaleur"],[5,"Imposer une étiquette énergie sur les appareils"]],"enteteLignes":true},{"id":"voix","type":"texte","genre":"source","titre":"Trois habitants s’expriment","source":"Prises de parole écrites pour l’exercice.","blocs":["Anaïs : « La technologie réglera tout : avec des éoliennes et des batteries plus performantes, on produira plus en polluant moins. »","Bastien : « Il faut répondre aux besoins d’aujourd’hui sans priver les générations futures de leurs ressources. »","Chloé : « Même avec de nouvelles techniques, on ne pourra pas produire toujours plus sans abîmer la planète : il faut produire moins. »"]}],"questions":[{"enonce":"Touche la mesure qui fixe un plafond d’émissions et laisse s’échanger les droits : un marché de quotas.","aide":"Cherche les mots « plafonner » et « échangeables ».","type":"zone","document":"mesures","multiple":false},{"enonce":"Associe chaque habitant à la position qu’il défend.","aide":"L’une fait confiance à la technique, l’une pense aux générations futures, l’une conteste le découplage.","type":"association","gauche":[{"id":"g0","texte":"Anaïs"},{"id":"g1","texte":"Bastien"},{"id":"g2","texte":"Chloé"}],"droite":[{"id":"d0","texte":"Décroissance"},{"id":"d1","texte":"Développement durable"},{"id":"d2","texte":"Croissance verte"}]},{"enonce":"Une usine émet 400 tonnes de CO₂. Quelle somme paierait-elle avec la mesure 2, en euros ?","aide":"Multiplie le nombre de tonnes par le prix de la tonne.","type":"nombre","unite":"€"},{"enonce":"Avec la mesure 3, chacune des cinq usines reçoit 200 tonnes de droits. Une usine émet 260 tonnes : combien de tonnes de droits doit-elle acheter ?","aide":"Compare ses émissions aux droits dont elle dispose.","type":"nombre","unite":"t"},{"enonce":"Quelle est la différence de principe entre la taxe (mesure 2) et le marché de quotas (mesure 3) ?","aide":"Taxer, c’est renchérir ; échanger des quotas, c’est plafonner.","type":"choix","options":[{"id":"a","texte":"Aucune différence : ce sont deux formes d’interdiction"},{"id":"b","texte":"La taxe fixe un prix ; le quota fixe une quantité d’émissions"},{"id":"c","texte":"La taxe interdit tout rejet ; le quota autorise tout le monde"},{"id":"d","texte":"La taxe fixe une quantité ; le quota fixe un prix des émissions"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"La mesure 3 est un **marché de quotas** : on fixe la quantité maximale d’émissions et le prix des droits résulte des échanges."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Anaïs parie sur le **découplage** par le progrès technique (croissance verte) ; Bastien reprend la définition du **développement durable** ; Chloé conteste qu’un découplage suffise : c’est la **décroissance**."},{"cle":{"type":"nombre","valeur":20000,"tolerance":0},"affichage":"20 000 €","explication":"400 × 50 = **20 000 €**. C’est le principe pollueur-payeur : celui qui pollue supporte le coût."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 t","explication":"260 − 200 = **60 tonnes** de droits à acheter à une usine qui émet moins que son quota."},{"cle":{"type":"choix","ids":["b"]},"explication":"Taxer, c’est **renchérir** le comportement polluant (le prix est fixé) ; le marché de quotas **fixe la quantité** d’émissions et le prix résulte des échanges."}]$ex$::jsonb),
  ('c34c6023-5016-52d1-90a5-bef26ea06279'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un billet, un job d’été, des livres sterling : trois marchés","competence":"analyser-document","situation":"Jade et Lucas s’écrivent à quelques jours des vacances. Sans le savoir, ils parlent de trois marchés différents.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de Jade et Lucas","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Lucas","emoji":"🧑","cote":"gauche"},{"nom":"Jade","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Lucas","texte":"Tu as ton billet pour le concert ?"},{"qui":"Jade","texte":"Oui, je l’ai acheté sur une appli de vente entre particuliers."},{"qui":"Lucas","texte":"Et ta sœur, elle a trouvé un job d’été ?"},{"qui":"Jade","texte":"Oui, la mairie l’a embauchée pour juillet."},{"qui":"Lucas","texte":"Moi, pour Londres, j’ai changé mes euros en livres. Mais l’an dernier, un inconnu m’a pris 30 € pour un billet qu’il n’a jamais livré : impossible de le retrouver."}]}],"questions":[{"enonce":"Associe chaque situation du dialogue au marché dont elle relève.","aide":"Un bien ou un service, un travail contre salaire, des monnaies qu’on échange entre elles.","type":"association","gauche":[{"id":"g0","texte":"Acheter un billet sur une appli de vente entre particuliers"},{"id":"g1","texte":"Être embauchée pour l’été"},{"id":"g2","texte":"Changer des euros en livres"}],"droite":[{"id":"d0","texte":"Marché des changes"},{"id":"d1","texte":"Marché du travail"},{"id":"d2","texte":"Marché de biens et services"}]},{"enonce":"Touche le mot qui montre qu’un marché peut exister sans lieu physique.","aide":"Cherche le support en ligne qui met en relation des particuliers.","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces marchés selon leur forme.","aide":"Un marché physique a un lieu (halle, place, salle) ; un marché dématérialisé a une plateforme.","type":"categories","categories":[{"id":"c0","texte":"Marché physique"},{"id":"c1","texte":"Marché dématérialisé"}],"items":[{"id":"i0","texte":"Une halle couverte le samedi matin"},{"id":"i1","texte":"Une application de covoiturage"},{"id":"i2","texte":"Une salle de marché"},{"id":"i3","texte":"Un site de vente entre particuliers"}]},{"enonce":"Lucas a payé un inconnu qui n’a jamais livré le billet. Quelle condition de l’échange marchand a manqué ?","aide":"Sans confiance, pas d’échange : qui oblige l’inconnu à tenir sa promesse ?","type":"choix","options":[{"id":"a","texte":"Une monnaie, car il a payé avec autre chose que des euros"},{"id":"b","texte":"Des vendeurs en nombre suffisant sur ce marché"},{"id":"c","texte":"Des contrats garantis, pour que la parole donnée soit tenue"},{"id":"d","texte":"Un lieu physique où se rencontrer vraiment"}],"multiple":false}]}$ex$::jsonb,
