  ('c34c6023-5016-52d1-90a5-bef26ea06279'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Valmont : quatre marchés, quatre structures","competence":"lire-tableau","situation":"La ville imaginaire de Valmont compte plusieurs marchés très différents. Un étudiant en économie veut les classer selon le nombre d’offreurs et la nature du produit.","documents":[{"id":"marches","type":"tableau","titre":"Quatre marchés de Valmont","source":"Situations imaginées pour l’exercice.","colonnes":["Marché","Les offreurs","Le produit"],"lignes":[["Le blé vendu aux minotiers","Des milliers d’agriculteurs : aucun ne pèse sur le prix","Identique d’un producteur à l’autre"],["L’eau du robinet","Un seul fournisseur","Le même pour tous"],["Les grandes surfaces","Trois enseignes se partagent presque tout","Très variés"],["Les boulangeries du centre","Une douzaine d’artisans","Différenciés par la recette et la marque"]],"enteteLignes":true},{"id":"parts","type":"tableau","titre":"Parts de marché des grandes surfaces","source":"Chiffres imaginés pour l’exercice.","colonnes":["Enseigne","Part de marché (%)"],"lignes":[["Enseigne A",45],["Enseigne B",35],["Enseigne C",15],["Autres commerces",5]],"enteteLignes":true}],"questions":[{"enonce":"Classe chaque marché dans sa structure.","aide":"Compte les offreurs : très nombreux, un seul, quelques-uns, nombreux avec des produits différenciés.","type":"categories","categories":[{"id":"c0","texte":"Concurrence parfaite"},{"id":"c1","texte":"Monopole"},{"id":"c2","texte":"Oligopole"},{"id":"c3","texte":"Concurrence monopolistique"}],"items":[{"id":"i0","texte":"Les boulangeries du centre"},{"id":"i1","texte":"Le blé vendu aux minotiers"},{"id":"i2","texte":"L’eau du robinet"},{"id":"i3","texte":"Les grandes surfaces"}]},{"enonce":"Touche ce qui montre qu’il s’agit d’un monopole.","aide":"Un monopole, c’est un seul offreur.","type":"zone","document":"marches","multiple":false},{"enonce":"Quelle part du marché détiennent à elles deux les enseignes A et B, en % ?","aide":"Additionne les deux plus grandes parts.","type":"nombre","unite":"%"},{"enonce":"Pourquoi le marché des boulangeries du centre n’est-il pas de concurrence parfaite ?","aide":"Relis la dernière colonne du tableau pour les boulangeries.","type":"choix","options":[{"id":"a","texte":"Les produits sont différenciés par la recette et la marque"},{"id":"b","texte":"Un seul artisan fixe le prix pour tous les autres"},{"id":"c","texte":"Il n’y a aucun acheteur sur ce marché"},{"id":"d","texte":"Il y a beaucoup trop d’artisans pour que la concurrence existe"}],"multiple":false}]}$ex$::jsonb,
