  ('c34c6023-5016-52d1-90a5-bef26ea06279'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Cimenval : un rachat, une entente, un abus ?","competence":"argumenter","situation":"Sur le marché du ciment de la région imaginaire de Cimenval, l’autorité de la concurrence examine trois affaires. Elle doit dire laquelle relève de quelle pratique, et ce qu’elle peut décider.","documents":[{"id":"parts","type":"tableau","titre":"Parts de marché des fabricants de ciment","source":"Chiffres imaginés pour l’exercice.","colonnes":["Fabricant","Avant le rachat (%)"],"lignes":[["Entreprise A",50],["Entreprise B",30],["Entreprise C",12],["Entreprise D",8]],"enteteLignes":true},{"id":"affaires","type":"texte","genre":"source","titre":"Trois dossiers","source":"Dossiers imaginés pour l’exercice.","blocs":["Dossier 1. Les entreprises A, C et D se téléphonent chaque mois pour fixer ensemble un prix minimal.","Dossier 2. L’entreprise A annonce le rachat de l’entreprise B.","Dossier 3. Un distributeur en position dominante vend à perte pendant des mois pour évincer un petit concurrent."]}],"questions":[{"enonce":"Si A rachète B, quelle part du marché l’entreprise A détiendra-t-elle, en % ?","aide":"Additionne les parts de A et de B.","type":"nombre","unite":"%"},{"enonce":"Associe chaque dossier à la pratique que surveille l’autorité de la concurrence.","aide":"Un accord entre concurrents, un rachat, l’usage d’un pouvoir de marché pour évincer.","type":"association","gauche":[{"id":"g0","texte":"Dossier 1"},{"id":"g1","texte":"Dossier 2"},{"id":"g2","texte":"Dossier 3"}],"droite":[{"id":"d0","texte":"Une concentration"},{"id":"d1","texte":"Un abus de position dominante"},{"id":"d2","texte":"Une entente sur les prix"}]},{"enonce":"Face au rachat de B par A, que peut faire l’autorité de la concurrence ?","aide":"Regarde la part de marché de A après le rachat.","type":"choix","options":[{"id":"a","texte":"L’interdire ou y mettre des conditions, car la concurrence serait trop réduite"},{"id":"b","texte":"Le laisser faire : les parts de marché n’ont aucune importance"},{"id":"c","texte":"L’accepter : plus une entreprise est grande, mieux le marché fonctionne"},{"id":"d","texte":"Sanctionner B, qui n’a rien décidé dans cette opération"}],"multiple":false},{"enonce":"Range ces biens selon qu’ils peuvent légalement s’échanger sur un marché ou non.","aide":"Certains échanges sont interdits par la loi : on ne vend légalement ni organes ni voix électorales.","type":"categories","categories":[{"id":"c0","texte":"Échangeable sur un marché"},{"id":"c1","texte":"Soustrait au marché"}],"items":[{"id":"i0","texte":"Une place de concert"},{"id":"i1","texte":"Une voix lors d’une élection"},{"id":"i2","texte":"Un vélo d’occasion"},{"id":"i3","texte":"Un organe humain"}]}]}$ex$::jsonb,
