   $ex${"titre":"Le prix des tomates au marché du samedi","competence":"lire-tableau","situation":"Au marché du samedi, Ilyes relève ce que les acheteurs voudraient acheter et ce que les maraîchers voudraient vendre, selon le prix du kilo de tomates.","documents":[{"id":"tomates","type":"tableau","titre":"Tomates : quantités souhaitées selon le prix","source":"Relevé imaginé pour l’exercice.","colonnes":["Prix du kilo (€)","Quantité demandée (kg)","Quantité offerte (kg)"],"lignes":[[1,100,20],[2,80,40],[3,60,60],[4,40,80],[5,20,100]]}],"questions":[{"enonce":"Touche le prix pour lequel la quantité offerte égale la quantité demandée.","aide":"Cherche la ligne où les deux dernières colonnes affichent le même nombre.","type":"zone","document":"tomates","multiple":false},{"enonce":"Quelle quantité s’échange à ce prix d’équilibre, en kilogrammes ?","aide":"Lis la quantité demandée (ou offerte) à 3 €.","type":"nombre","unite":"kg"},{"enonce":"À 4 € le kilo, de combien de kilogrammes l’offre dépasse-t-elle la demande ?","aide":"Soustrais la quantité demandée de la quantité offerte, sur la ligne à 4 €.","type":"nombre","unite":"kg"},{"enonce":"À 2 € le kilo, la demande est de 80 kg et l’offre de 40 kg. Que va-t-il se passer ?","aide":"Qui est en excès à 2 € : les acheteurs ou les vendeurs ?","type":"choix","options":[{"id":"a","texte":"Rien : à 2 €, le marché est déjà à l’équilibre naturel"},{"id":"b","texte":"Invendus : les maraîchers vont devoir baisser leur prix"},{"id":"c","texte":"Pénurie : des acheteurs resteront sans tomates, le prix monte"},{"id":"d","texte":"Le prix va baisser, car la demande est très forte"}],"multiple":false}]}$ex$::jsonb,
