   $ex${"titre":"Un gel de printemps sur le marché des tomates","competence":"lire-graphique","situation":"Sur un marché de tomates imaginaire, une économiste trace les courbes d’offre et de demande. Puis un gel de printemps détruit une partie de la récolte.","documents":[{"id":"courbes","type":"graphique","forme":"courbe","titre":"Offre et demande de tomates","source":"Courbes imaginées pour l’exercice.","categories":["1 €","2 €","3 €","4 €","5 €","6 €"],"series":[{"nom":"Demande","valeurs":[100,85,70,55,40,25],"teinte":"violet"},{"nom":"Offre","valeurs":[10,25,40,55,70,85],"teinte":"ambre"}],"axeY":{"titre":"Quantité","unite":"en kg","min":0,"max":100,"pas":20},"axeX":{"titre":"Prix du kilo"}},{"id":"gel","type":"texte","genre":"article","titre":"Le gel de la nuit du 14 avril","source":"Article imaginé pour l’exercice.","blocs":["Un gel tardif a détruit une partie des plants. À chaque prix, les maraîchers proposent désormais moins de tomates qu’avant. Les consommateurs, eux, n’ont pas changé leurs habitudes."]}],"questions":[{"enonce":"Touche le prix d’équilibre, là où les deux courbes se croisent.","aide":"Cherche le prix où l’offre et la demande indiquent la même quantité.","type":"zone","document":"courbes","multiple":false},{"enonce":"Quelle quantité s’échange à l’équilibre, en kilogrammes ?","aide":"Lis la hauteur des courbes au point où elles se croisent.","type":"nombre","unite":"kg"},{"enonce":"À 6 € le kilo, de combien l’offre excède-t-elle la demande, en kilogrammes ?","aide":"Lis l’offre (85) et la demande (25) à 6 €, puis soustrais.","type":"nombre","unite":"kg"},{"enonce":"Que provoque le gel sur les courbes ?","aide":"Qui a changé de comportement : les vendeurs ou les acheteurs ? Et pour tous les prix ?","type":"choix","options":[{"id":"a","texte":"La courbe de demande se déplace vers la gauche"},{"id":"b","texte":"La courbe d’offre se déplace vers la gauche"},{"id":"c","texte":"On se déplace le long de la courbe d’offre"},{"id":"d","texte":"La courbe de demande se déplace vers la droite"}],"multiple":false},{"enonce":"Quel est l’effet de ce déplacement sur le nouvel équilibre ?","aide":"Imagine la courbe d’offre décalée vers la gauche : où croise-t-elle la demande ?","type":"choix","options":[{"id":"a","texte":"Un prix identique, mais une quantité plus forte"},{"id":"b","texte":"Un prix plus faible et une quantité échangée plus forte"},{"id":"c","texte":"Un prix plus élevé et une quantité échangée plus forte"},{"id":"d","texte":"Un prix plus élevé et une quantité échangée plus faible"}],"multiple":false}]}$ex$::jsonb,
